import unittest

from hourglass.rounding import check_step, round_labels
from hourglass.parsing import parse_span

class LabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        self.assertEqual(
            round_labels([parse_span("09:04-17:12")], 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_exact_half_rounds_up(self):
        self.assertEqual(
            round_labels([parse_span("09:15-10:45")], 30),
            ["09:30-11:00 (1h 30m)"],
        )

    def test_step_of_one_keeps_times(self):
        self.assertEqual(
            round_labels([parse_span("09:07-10:00")], 1),
            ["09:07-10:00 (0h 53m)"],
        )

    def test_keeps_order_of_spans(self):
        spans = [
            parse_span("13:00-14:10"),
            parse_span("09:00-10:00"),
        ]
        self.assertEqual(
            round_labels(spans, 15),
            ["13:00-14:15 (1h 15m)", "09:00-10:00 (1h 0m)"],
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_span_that_rounds_to_nothing(self):
        with self.assertRaises(ValueError):
            round_labels([parse_span("09:00-09:05")], 15)

class StepTests(unittest.TestCase):
    def test_divisors_of_an_hour_are_accepted(self):
        steps = (1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60)
        for step in steps:
            with self.subTest(step=step):
                check_step(step)

    def test_other_steps_are_rejected(self):
        for step in (0, -15, 7, 45, 90, 2.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    check_step(step)

    def test_bad_step_is_rejected_without_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 7)
